    'docs_exp_void_desc' => 'أبطل المصروفات غير الصحيحة مع الاحتفاظ بها في سجل التدقيق',
    'docs_faq_a1' => 'بعد تسجيل الدخول، أضف عقارك الأول، وأنشئ وحدات داخله، وسجّل المستأجرين، وأنشئ العقود، وابدأ في تسجيل الدفعات. اتبع دليل البدء للحصول على تعليمات خطوة بخطوة.',
    'docs_faq_a10' => 'تواصل مع فريق الدعم لدينا عبر واتساب أو البريد الإلكتروني. يحصل مشتركو مستوى Enterprise على دعم ذي أولوية مع أوقات استجابة أسرع.',
    'docs_faq_a2' => 'نعم! FIS Real Estate هو تطبيق ويب تقدمي (PWA). ثبّته على جهازك وواصل العمل دون اتصال بالإنترنت. ستتم مزامنة تغييراتك تلقائيًا عند إعادة الاتصال بالإنترنت.',
    'docs_faq_a3' => 'تُفوتر شهريًا بناءً على عدد الوحدات التي تديرها مضروبًا في سعر مستواك. مستوى Basic هو %1$s TZS/وحدة/شهر، ومستوى Professional هو %2$s، ومستوى Enterprise هو %3$s. قد تُطبق خصومات.',
    'docs_faq_a4' => 'تواصل مع فريق دعم FIS Real Estate عبر واتساب أو البريد الإلكتروني لطلب ترقية المستوى. سيتم تحديث اشتراكك وستحصل على إمكانية الوصول إلى الميزات الجديدة فورًا.',
    'docs_faq_a5' => 'نعم، مع مستوى Professional أو أعلى. تتيح بوابة المستأجر للمستأجرين تسجيل الدخول وعرض رصيدهم وسجل الدفعات وتفاصيل العقد. يمكنك تفعيل أو تعطيل الوصول إلى البوابة لكل مستأجر.',
    'docs_faq_a6' => 'تُحسب رسوم التأخير تلقائيًا بناءً على إعداداتك. تحدد نوع الرسوم (نسبة مئوية أو ثابتة) وفترة السماح والحد الأقصى. تُطبق الرسوم عندما لا يُدفع الإيجار بحلول تاريخ الاستحقاق مضافًا إليه فترة السماح.',
    'docs_faq_a7' => 'نعم، يمكنك إدارة عدد غير محدود من العقارات دون تكلفة إضافية. يمكن أن يكون لكل عقار إعداداته ووحداته ومستأجروه الخاصون. تُجمّع لوحة التحكم البيانات عبر جميع عقاراتك.',
    'docs_faq_a8' => 'يدعم النظام الإنجليزية والسواحيلية (Kiswahili) والعربية (بتخطيط من اليمين إلى اليسار). بدّل اللغات في أي وقت باستخدام أيقونة الكرة الأرضية في الشريط العلوي.',
    'docs_faq_a9' => 'تحتوي معظم عروض القوائم والتقارير على زر تصدير/CSV. انقر عليه لتنزيل البيانات كملف CSV يُفتح في Excel أو Google Sheets. يمكن للمسؤولين أيضًا إنشاء نسخ احتياطية كاملة لقاعدة البيانات من صفحة النسخ الاحتياطي.',
