    // Page introductions (part 35)
    'intro_next' => 'التالي:',
    'intro_hide' => 'إخفاء',
    'intro_show' => 'ما هذه الصفحة؟',
    'intro_go_units' => 'إضافة وحدات',
    'intro_go_unit_new' => 'إضافة وحدة',
    'intro_go_tenants' => 'تسجيل المستأجرين',
    'intro_go_tenant_new' => 'إضافة مستأجر',
    'intro_go_lease_new' => 'إنشاء عقد',
    'intro_go_payments' => 'المدفوعات',
    'intro_go_payment_new' => 'تسجيل دفعة',
    'intro_go_deposit_new' => 'تسجيل الوديعة',
    'intro_go_charges' => 'عرض المستحقات',
    'intro_go_floats' => 'إيداع النقد',
    'intro_go_payables' => 'الاعتمادات',
    'intro_go_mappings' => 'ربط الحسابات',
    'intro_go_statements' => 'القوائم المالية',
    'intro_go_journal' => 'اليومية',
    'intro_go_tb' => 'ميزان المراجعة',
    'intro_go_aged' => 'أعمار الذمم',
    'intro_properties_index_what' => 'كل مبنى تديره. العقار يضم وحدات، وكل ما عداه — المستأجرون والعقود والإيجار — مرتبط بتلك الوحدات.',
    'intro_properties_index_how' => 'ابدأ من هنا في نظام جديد. أضف عقارًا ثم أضف وحداته. انقر على أي عقار لعرض وحداته وصوره وتكاليفه.',
    'intro_properties_create_what' => 'أضف مبنى. الاسم وحده مطلوب — والباقي يمكن إكماله لاحقًا.',
    'intro_properties_create_how' => 'امنحه اسمًا يتعرف عليه الناس في التقارير. بعد الحفظ، أضف وحداته.',
    'intro_properties_view_what' => 'كل ما يخص عقارًا واحدًا: وحداته، وكم منها مشغول، وصوره وما كلفك.',
    'intro_properties_view_how' => 'استخدم علامات التبويب للتنقل بين الوحدات والصور والمصروفات. يتحدث الإشغال تلقائيًا مع بدء العقود وانتهائها.',
    'intro_units_index_what' => 'كل مساحة قابلة للتأجير في عقاراتك، مع إيجارها وما إذا كان أحد يشغلها.',
    'intro_units_index_how' => 'تصبح الوحدة مشغولة تلقائيًا عند إنشاء عقد عليها، وشاغرة عند انتهائه. حدد الإيجار هنا — تستخدمه العقود الجديدة كقيمة افتراضية.',
    'intro_units_create_what' => 'أضف مساحة قابلة للتأجير إلى عقار — شقة أو غرفة أو محل أو مكتب.',
    'intro_units_create_how' => 'الإيجار والعملة اللذان تحددهما هنا يصبحان الافتراضيين عند إنشاء عقد لهذه الوحدة. اترك الحالة شاغرة؛ فهي تتغير تلقائيًا عند بدء العقد.',
    'intro_units_view_what' => 'وحدة واحدة: عقدها الحالي وإيجارها وصورها وسجلها.',
    'intro_units_view_how' => 'إذا ظهرت الوحدة مشغولة دون وجود عقد، فقد حُذف عقد قديم دون تحريرها — صحّح ذلك بتعديل حالة الوحدة.',
    'intro_tenants_index_what' => 'كل من يستأجر منك، سابقًا وحاليًا.',
    'intro_tenants_index_how' => 'سجّل المستأجر قبل إدراجه في عقد. انقر على الاسم لعرض عقوده ومدفوعاته ومستنداته وصورة هويته.',
    'intro_tenants_create_what' => 'سجّل شخصًا حتى يمكن إدراجه في عقد.',
    'intro_tenants_create_how' => 'الاسم والهاتف فقط مطلوبان. يمكن إضافة الرقم الضريبي وأقرب الأقارب والعمل الآن أو لاحقًا — وتُرفع صورة الهوية من صفحة المستأجر بعد الحفظ.',
    'intro_tenants_view_what' => 'مستأجر واحد: عقوده وما دفعه وما عليه ومستنداته وهويته.',
    'intro_tenants_view_how' => 'ارفع صورة الهوية في بطاقة وثيقة الهوية على اليمين. استخدم علامة تبويب المستندات لكل ما عداها — العقود والمراسلات والمراجع.',
    'intro_tenants_edit_what' => 'تعديل بيانات المستأجر.',
    'intro_tenants_edit_how' => 'صورة الهوية ليست هنا — تُدار من صفحة المستأجر نفسها لأنها ملف وليست حقلًا.',
    'intro_leases_index_what' => 'كل اتفاق يربط مستأجرًا بوحدة، مع الإيجار والمدة ودورية الدفع.',
    'intro_leases_index_how' => 'العقد هو ما يجعل الإيجار يُستحق. إلى أن يكون للوحدة عقد ساري، لا يُطالَب بشيء ولا تظهر متأخرات.',
    'intro_leases_create_what' => 'أدرج مستأجرًا في وحدة وفق شروط متفق عليها.',
    'intro_leases_create_how' => 'تظهر الوحدات الشاغرة أو المحجوزة فقط — إذا غابت وحدة فهي ما زالت مشغولة بعقد سابق. يُملأ الإيجار والوديعة من الوحدة، وتحدد دورية الدفع عدد مرات استحقاق الإيجار.',
    'intro_leases_view_what' => 'عقد واحد: شروطه وما دُفع مقابله ومستنداته.',
    'intro_leases_view_how' => 'يُستحق الإيجار تلقائيًا كل فترة اعتبارًا من تاريخ البدء. استخدم الطباعة للحصول على عقد قابل للتوقيع من قالبك.',

    // Page introductions, money and ledger pages (part 35b)
    'intro_payments_index_what' => 'كل دفعة مستلمة، والإيصالات الصادرة عنها.',
    'intro_payments_index_how' => 'تسدد الدفعة أقدم المستحقات غير المسددة أولًا. إذا دُفع جزء، يبقى الباقي متأخرات — والدفعة الجزئية لا تُعامل كعدم دفع.',
    'intro_payments_create_what' => 'سجّل مبلغًا مستلمًا من مستأجر.',
    'intro_payments_create_how' => 'اختر طريقة الدفع: النقد والشيك يدخلان عهدتك حتى تودعهما، أما التحويلات البنكية فتذهب مباشرة إلى البنك. ويُطبَّق المبلغ تلقائيًا على أقدم المستحقات.',
    'intro_payments_view_what' => 'دفعة واحدة: ما سددته وإيصالها والمستندات المرفقة بها.',
    'intro_payments_view_how' => 'عكس الدفعة يعيد فتح المستحقات التي سددتها، فتعود متأخرات المستأجر كما كانت.',
    'intro_deposits_index_what' => 'الودائع التأمينية التي تحتفظ بها وما جرى لها.',
    'intro_deposits_index_how' => 'الوديعة مال المستأجر حتى يفقدها، فهي محتفظ بها لا مكتسبة. ويتطلب ردها أو مصادرتها اعتماد شخص آخر.',
    'intro_deposits_create_what' => 'سجّل وديعة مستلمة مقابل عقد.',
    'intro_deposits_create_how' => 'يدخل النقد عهدتك تمامًا كدفعة إيجار. وتُسجَّل الوديعة كمال تحتفظ به للمستأجر لا كإيراد.',
    'intro_deposits_view_what' => 'وديعة واحدة: المحتفظ به وأي خصومات وحالة الرد.',
    'intro_deposits_view_how' => 'فصّل الخصومات قبل الرد. زرّا الرد والمصادرة يرفعان طلبًا بدل التنفيذ الفوري — ويعتمده شخص آخر من دفتر الأستاذ، الذمم الدائنة.',
    'intro_expenses_index_what' => 'ما تنفقه على تشغيل العقارات — الكهرباء والرواتب والإصلاحات.',
    'intro_expenses_index_how' => 'سجّل الفاتورة عند وصولها، مدفوعة كانت أم لا. تُحتسب التكلفة على الشهر الذي نشأت فيه، وتظل مستحقة حتى يعتمد أحدهم الدفع.',
    'intro_ledger_index_what' => 'دليل حساباتك — الحسابات البنكية وصناديق النقد وبنود الإيرادات والمصروفات التي يُسجَّل كل شيء مقابلها.',
    'intro_ledger_index_how' => 'أعدّ هذا قبل تسجيل المدفوعات. أضف حساباتك البنكية ثم اربط البنك الافتراضي ليعرف التحويل وجهته. الحسابات الموسومة بـ«النظام» تُنشأ لك ولا يمكن حذفها.',
    'intro_ledger_mappings_what' => 'أين تُقيَّد القيود التلقائية. كل حدث — إيجار أو وديعة أو تحويل بنكي — يشير إلى حساب واحد.',
    'intro_ledger_mappings_how' => 'الصفوف المميزة غير مربوطة بعد ويجب ضبطها قبل أن تُقيَّد تلك الأحداث. وإقفال الدفاتر في الأسفل يمنع تسجيل أي شيء في التاريخ أو قبله.',
    'intro_ledger_charges_what' => 'ما يدين به المستأجرون: الإيجار عند استحقاقه والمرافق ورسوم التأخير.',
    'intro_ledger_charges_how' => 'تُنشأ المستحقات تلقائيًا كل فترة لكل عقد ساري. إن كانت هذه فارغة فلم يعمل المولّد اليومي بعد — ولا مديونية قبل وجود مستحقات.',
    'intro_ledger_floats_what' => 'النقد الذي يحتفظ به موظفوك نيابة عن الشركة، والإيداعات التي أعلنوا عنها.',
    'intro_ledger_floats_how' => 'تظهر العهدة تلقائيًا أول مرة يسجل فيها أحدهم دفعة نقدية. استخدم «إيداع النقد» عند وصول المال إلى البنك — ولا تنخفض العهدة إلا بعد اعتماد شخص ثانٍ.',
    'intro_ledger_payables_what' => 'كل ما ينتظر السداد أو الاعتماد: فواتير الموردين وطلبات رد الودائع من زميل.',
    'intro_ledger_payables_how' => 'الاعتماد هو ما يُخرج المال فعليًا. لا يمكنك اعتماد طلبك، لذا يحتاج شخصان على الأقل إلى صلاحية الاعتماد.',
    'intro_ledger_journal_what' => 'كل قيد في الدفاتر، سواء سجّله شخص أو النظام.',
    'intro_ledger_journal_how' => 'القيود المنتظرة للاعتماد لا تؤثر في شيء حتى تُعتمد. والقيود المرحّلة لا تُعدَّل أبدًا — صحّح الخطأ بعكسه، ويبقى الاثنان في السجل.',
    'intro_ledger_create_what' => 'سجّل يدويًا ما لا يستطيع النظام استنتاجه — رصيدًا افتتاحيًا أو تصحيحًا أو تسوية.',
    'intro_ledger_create_how' => 'يجب أن يتساوى المدين والدائن قبل الإرسال، وأن يستخدم كل بند حسابًا بالعملة نفسها. ثم يعتمده شخص آخر.',
    'intro_ledger_view_what' => 'قيد واحد وبنوده ومن أنشأه واعتمده.',
    'intro_ledger_view_how' => 'لا يمكن تعديل قيد مرحّل أو حذفه. استخدم «عكس القيد» لإلغائه بقيد معاكس — ويبقى الأصل ظاهرًا موسومًا بأنه معكوس.',
    'intro_ledger_trial-balance_what' => 'فحص السلامة: إجمالي المدين مقابل إجمالي الدائن، لكل عملة.',
    'intro_ledger_trial-balance_how' => 'يجب أن يتساويا. يُتحقق من كل قيد عند حفظه، فإن اختلفا فقد غيّر شيء قاعدة البيانات خارج التطبيق.',
    'intro_ledger_statements_what' => 'الأرباح والخسائر، والميزانية العمومية، وربحية كل وحدة، ومن تأخر في السداد.',
    'intro_ledger_statements_how' => 'كل رقم رابط — انقر للانتقال إلى الحساب ثم إلى القيود وراءه. تُحتسب الإيرادات عند استحقاقها والمصروفات عند نشوئها، لا عند حركة النقد.',
    'intro_ledger_account_what' => 'كل حركة على حساب واحد مع رصيد جارٍ.',
    'intro_ledger_account_how' => 'هنا يُفسَّر أي رقم في القوائم. ويرتبط كل رقم قيد بالقيد الكامل الذي جاء منه.',

    // Page introduction links (part 35c)
    'intro_go_deposits' => 'الودائع',
    'intro_go_deductions' => 'الخصومات',
    'intro_go_expenses' => 'المصروفات',
    'intro_go_inquiries' => 'الاستفسارات',
    'intro_go_users' => 'المستخدمون',
    // Page introductions — batch 2 (part 35d)
    'intro_properties_edit_what' => 'تعديل بيانات العقار.',
    'intro_properties_edit_how' => 'تغيير الاسم يغيّر طريقة ظهوره في كل تقرير وكشف، بما في ذلك القديمة منها.',
    'intro_properties_photos_what' => 'صور المبنى — تفيد في إعلانات الشواغر وفي توثيق الحالة.',
    'intro_properties_photos_how' => 'الصور هنا تصف العقار ككل. أما صور شقة بعينها فتوضع على تلك الوحدة.',
    'intro_properties_settings_what' => 'قواعد تخص هذا العقار وحده، مثل دورة الإيجار وشروط رسوم التأخير.',
    'intro_properties_settings_how' => 'كل ما يُضبط هنا يتجاوز إعداد النظام العام لهذا العقار وحده. اترك الحقل فارغًا للاستمرار على القاعدة العامة.',
    'intro_units_edit_what' => 'تعديل بيانات الوحدة أو إيجارها.',
    'intro_units_edit_how' => 'تغيير الإيجار لا يمس العقود القائمة — فهي تحتفظ بالمبلغ المتفق عليه عند توقيعها. عدّل الإيجار في العقد نفسه لتغيير ما يُحتسب.',
    'intro_units_photos_what' => 'صور هذه الوحدة، للإعلانات ولتوثيق حالتها.',
    'intro_units_photos_how' => 'التقطها عند الدخول وعند المغادرة؛ فهي تحسم أغلب الخلافات حول التأمين قبل أن تبدأ.',
    'intro_leases_edit_what' => 'تعديل شروط عقد قائم.',
    'intro_leases_edit_how' => 'تغيير الإيجار أو الدورية يؤثر في المستحقات التي تُنشأ من الآن فصاعدًا. أما المستحقات المنشأة سابقًا فتبقى بمبالغها الأصلية — اعكسها إن كانت خاطئة.',
    'intro_leases_templates_what' => 'الصيغة المستخدمة عند طباعة عقد الإيجار.',
    'intro_leases_templates_how' => 'العناصر النائبة مثل {{rent_amount}} تُملأ من العقد عند الطباعة. حدّد واحدة كافتراضية لتستخدمها العقود الجديدة.',
    'intro_deposits_edit_what' => 'تصحيح بيانات تأمين مسجّل بالفعل.',
    'intro_deposits_edit_how' => 'الاسترداد والمصادرة لا يتمان هنا — بل يُطلبان من صفحة التأمين نفسها ويحتاجان إلى اعتماد.',
    'intro_payments_edit_what' => 'تصحيح بيانات دفعة مسجّلة بالفعل.',
    'intro_payments_edit_how' => 'لإلغاء الدفعة بالكامل، اعكسها من صفحتها بدلاً من ذلك — يعيد ذلك فتح المستحقات التي سدّدتها ويفكّها من الحسابات.',
    'intro_payments_bulk_what' => 'تسجيل عدة دفعات دفعة واحدة، ليوم الإيجار حين يطول الطابور.',
    'intro_payments_bulk_how' => 'كل سطر يُطبّق على أقدم مستحقات ذلك المستأجر غير المسددة، تمامًا كأي دفعة مفردة.',
    'intro_deposits_late-fees_what' => 'رسوم تُضاف عندما لا يُسدَّد الإيجار في موعده.',
    'intro_deposits_late-fees_how' => 'تُنشأ تلقائيًا بالمهمة اليومية وفق قواعد التأخير لديك. ويمكن الإعفاء من الرسم مع تسجيل السبب.',
    'intro_deposits_late-fee-settings_what' => 'القواعد التي تحدد متى يُفرض رسم التأخير وكم يبلغ.',
    'intro_deposits_late-fee-settings_how' => 'اضبط فترة سماح حتى لا يُعاقَب تأخر يوم واحد، وحدًا أقصى حتى لا تتضخم الرسوم على حساب متأخر منذ زمن طويل.',
    'intro_documents_index_what' => 'كل ملف محفوظ في النظام، وبماذا يرتبط كل منها.',
    'intro_documents_index_how' => 'صفِّ حسب الفئة أو حسب ما يتبعه المستند. الملفات المعلّمة سرّية تحمل إشارة لكنها تبقى ظاهرة لكل من يستطيع فتح هذه الصفحة.',
    'intro_documents_upload_what' => 'أضف ملفًا وأرفقه بعقار أو وحدة أو مستأجر أو عقد أو دفعة أو تأمين أو مصروف.',
    'intro_documents_upload_how' => 'الوصول إلى هنا من سجل معيّن يحدده مسبقًا، وهي أضمن طريقة لحفظ الملف في مكانه الصحيح.',
    'intro_documents_view_what' => 'مستند واحد: معاينة حيثما أمكن، والجهة التي يتبعها.',
    'intro_documents_view_how' => 'استخدم التنزيل لكل ما لا يستطيع المتصفح عرضه. التعديل يغيّر السجل لا الملف — أعد الرفع لاستبدال الملف نفسه.',
    'intro_inspections_index_what' => 'فحوص حالة الوحدات، عند الدخول أو المغادرة أو بشكل دوري.',
    'intro_inspections_index_how' => 'فحص المغادرة هو ما يبرر الخصم من التأمين، فأجرِه قبل رد أي تأمين.',
    'intro_inspections_create_what' => 'ابدأ فحص حالة لوحدة.',
    'intro_inspections_create_how' => 'اختر قالبًا لتحصل على قائمة جاهزة. وصوّر كل ما قد ترغب في المحاسبة عليه لاحقًا.',
    'intro_inspections_view_what' => 'فحص واحد: كل بند مفحوص وحالته وصوره.',
    'intro_inspections_view_how' => 'البنود المعلّمة كتالفة يمكن تحويلها إلى خصومات من التأمين، ومعها وصفها وصورها.',
    'intro_inspections_move-out_what' => 'الفحص الذي يجري عند مغادرة المستأجر، بمقارنة الوحدة بما كانت عليه عند استلامه لها.',
    'intro_inspections_move-out_how' => 'أكمله قبل رد التأمين — فالخصومات التي تتم بدونه يصعب الدفاع عنها.',
    'intro_inspections_deductions_what' => 'المبالغ المحتجزة من التأمين مقابل التلف أو التنظيف.',
    'intro_inspections_deductions_how' => 'ينبغي أن يستند كل خصم إلى ملاحظة في فحص. وما يتبقى بعد الخصومات هو ما يُردّ.',
    'intro_inspections_templates_what' => 'قوائم فحص قابلة لإعادة الاستخدام حتى يغطي كل فحص النقاط نفسها.',
    'intro_inspections_templates_how' => 'أنشئ قائمة لكل نوع عقار. القائمة الموحّدة هي ما يجعل فحصين قابلين للمقارنة.',
    'intro_maintenance_index_what' => 'طلبات الإصلاح والصيانة، من الإبلاغ حتى الإنجاز.',
    'intro_maintenance_index_how' => 'يمكن للمستأجرين رفعها من بوابتهم. عيّن مقاولاً وتابع التكلفة، ويمكن أن تصبح مصروفًا عند الانتهاء.',
    'intro_maintenance_create_what' => 'سجّل شيئًا يحتاج إلى إصلاح.',
    'intro_maintenance_create_how' => 'الصور والوصف الواضح يوفران زيارة ثانية. وحدّد الأولوية بصدق — إذا صار كل شيء عاجلاً فلا شيء عاجل.',
    'intro_maintenance_view_what' => 'طلب واحد: سجله وصوره ومن أُسند إليه وكم كلّف.',
    'intro_maintenance_view_how' => 'التكاليف المسجّلة هنا يمكن تحويلها إلى مصروف، وهو ما يدخلها في الحسابات.',
    'intro_maintenance_edit_what' => 'تعديل بيانات طلب صيانة.',
    'intro_maintenance_edit_how' => 'تحديث الحالة هو ما يُعلم المستأجر بأن هناك ما يجري، إن كان قد رفع الطلب من البوابة.',
    'intro_maintenance_contractors_what' => 'الأشخاص والشركات الذين تستعين بهم للإصلاحات.',
    'intro_maintenance_contractors_how' => 'تسجيل التخصص والسعر هنا يسرّع إسناد العمل ويمنحك ما تقارن به عند ارتفاع التكاليف.',
    'intro_maintenance_reports_what' => 'ما تكلفه الصيانة، حسب العقار والفئة والمقاول.',
    'intro_maintenance_reports_how' => 'استخدمه لرصد مبنى يكلف أكثر مما ينبغي، أو عطل متكرر يُرقَّع بدل أن يُصلَح.',
    'intro_utilities_index_what' => 'الماء والكهرباء وغيرها من الخدمات المعاد تحصيلها من المستأجرين.',
    'intro_utilities_index_how' => 'سجّل قراءة العداد، فتُحتسب القيمة من سعرك وتُضاف إلى ما على ذلك المستأجر.',
    'intro_utilities_readings_what' => 'قراءات العدادات، والمبالغ المحتسبة منها.',
    'intro_utilities_readings_how' => 'أدخل القراءة الحالية؛ والاستهلاك هو الفرق عن المرة السابقة. تحقق بعناية من أول قراءة لإيجار جديد — فكل ما بعدها يعتمد عليها.',
    'intro_utilities_types_what' => 'الخدمات التي تحاسب عليها، وكيف تُسعَّر كل منها.',
    'intro_utilities_types_how' => 'اختر السعر بالوحدة للخدمات المقيسة بعداد، أو مبلغًا ثابتًا شهريًا، أو شرائح حين يتغير السعر بتغيّر الاستهلاك.',
    'intro_vacancies_index_what' => 'الوحدات الشاغرة التي تعلن عنها، والاستفسارات التي تجتذبها.',
    'intro_vacancies_index_how' => 'الوحدات الشاغرة وحدها يمكن إدراجها. وينغلق الإعلان تلقائيًا عند إنشاء عقد على تلك الوحدة.',
    'intro_vacancies_create_what' => 'أعلن عن وحدة شاغرة.',
    'intro_vacancies_create_how' => 'الإيجار والوصف يأتيان من الوحدة. أضف صورًا — فالإعلان بلا صور يجتذب استفسارات أقل بكثير.',
    'intro_vacancies_view_what' => 'إعلان واحد: كيف يقرؤه الناس، ومن استفسر عنه.',
    'intro_vacancies_view_how' => 'حوّل استفسارًا واعدًا إلى مستأجر ثم إلى عقد — وهذا يغلق الإعلان تلقائيًا.',
    'intro_vacancies_inquiries_what' => 'من استفسروا عن وحدة شاغرة.',
    'intro_vacancies_inquiries_how' => 'علّم كل استفسار بأنه جرى التواصل بشأنه أو أنه أُغلق، حتى لا يُتابَع أحد مرتين أو يُنسى.',
    'intro_reports_index_what' => 'تقارير التشغيل — التحصيل والإشغال والمتأخرات.',
    'intro_reports_index_how' => 'هذه تقرأ سجلاتك اليومية. أما الحسابات نفسها فاستخدم لها كشوف دفتر الأستاذ.',
    'intro_reports_financial_what' => 'ما جرى تحصيله وإنفاقه خلال فترة.',
    'intro_reports_financial_how' => 'هذا يحتسب النقد وقت حركته. أما الأرباح والخسائر في دفتر الأستاذ فتحتسب الإيراد وقت استحقاقه، فالاثنان يجيبان عن سؤالين مختلفين.',
    'intro_reports_occupancy_what' => 'كم من مساحتك يدرّ دخلاً، وكم منها واقف فارغًا.',
    'intro_reports_occupancy_how' => 'الإشغال يتبع حالة العقود، فدقته من دقة عقودك. ووحدة ما زالت معلّمة مشغولة بعد انتهاء عقدها ترفع الرقم بغير وجه حق.',
    'intro_reports_custom_what' => 'ابنِ تقريرك بنفسك باختيار الأعمدة والمرشحات التي تريدها.',
    'intro_reports_custom_how' => 'صدّر إلى جدول بيانات كل ما تحتاج إلى إعادة معالجته أو إرساله إلى غيرك.',
    'intro_expenses_reports_what' => 'ما أنفقته، موزعًا حسب العقار والفئة.',
    'intro_expenses_reports_how' => 'تُحتسب التكاليف على الشهر الذي نشأت فيه، فالفاتورة المدفوعة متأخرة تقع في شهرها الصحيح رغم ذلك.',
    'intro_payments_gateway-transactions_what' => 'الدفعات التي وردت عبر بوابة الدفع الإلكتروني.',
    'intro_payments_gateway-transactions_how' => 'تسجل نفسها وتُقيَّد إلى البنك مباشرة، إذ لم يتناول أحد النقد. والمعاملة الفاشلة هنا تعني أن المستأجر لم يُخصم منه شيء.',
    'intro_payments_gateway-settings_what' => 'اربط مزوّد دفع إلكتروني ليتمكن المستأجرون من الدفع بأنفسهم.',
    'intro_payments_gateway-settings_how' => 'جرّب بدفعة حقيقية صغيرة قبل الإعلان عنها — فالمفتاح الخاطئ يفشل بصمت عند المستأجر.',
    'intro_payments_gateway-pay_what' => 'الصفحة التي يراها المستأجر عند الدفع إلكترونيًا.',
    'intro_payments_gateway-pay_how' => 'افتحها لترى ما سيرونه. والدفعة الناجحة تسجل نفسها وتسدد أقدم مستحقاتهم.',
    'intro_settings_index_what' => 'بيانات الشركة والعملة والوحدات والقواعد العامة للنظام.',
    'intro_settings_index_how' => 'تبويب الوحدات يشغّل ميزات كاملة ويوقفها. وبعضها يحتاج باقة أعلى، وهي معلّمة بذلك.',
    'intro_settings_reminders_what' => 'رسائل تلقائية تخبر المستأجرين بما استحق وما تأخر.',
    'intro_settings_reminders_how' => 'التذكيرات تقرأ المستحق فعلاً، فلا يُلاحَق مستأجر قد سدّد. جرّب القالب على نفسك قبل تشغيله.',
    'intro_settings_backup_what' => 'صدّر بياناتك، أو أدخلها من نظام آخر.',
    'intro_settings_backup_how' => 'خذ نسخة قبل أي عمل كبير — استيراد بالجملة أو تنظيف بيانات أو تغيير لست واثقًا منه.',
    'intro_masters_users_what' => 'من يستطيع الدخول، وما المسموح لكل منهم بفعله.',
    'intro_masters_users_how' => 'امنح صلاحية الاعتماد لشخصين على الأقل — فلا أحد يعتمد عمله بنفسه، وبمعتمد واحد لن يُعتمد شيء أبدًا.',
    'intro_masters_roles_what' => 'مجموعات صلاحيات تحدد ما يراه المستخدم وما يغيّره.',
    'intro_masters_roles_how' => 'امنح كل دور أقل ما يحتاجه. فحارس لا يستطيع حذف دفعة لن يحذفها بالخطأ.',
    // Ledger documentation page (part 36)
    'docs_ledger_guide' => 'دفتر الأستاذ المحاسبي',
    'docs_led_intro' => 'يقوم خلف النظام كله دفتر أستاذ كامل بالقيد المزدوج. الإيجارات والدفعات والتأمينات والمصروفات تُرحَّل إليه تلقائيًا، فتبقى دفاترك صحيحة دون أن يكتب أحد قيدًا واحدًا.',
    'docs_led_intro_note' => 'لست مضطرًا لفهم المحاسبة بالقيد المزدوج لاستخدام النظام. سجّل الدفعات والمصروفات كما اعتدت؛ ودفتر الأستاذ يتولى نفسه. تشرح هذه الصفحة ما يفعله، والشاشات القليلة التي يطلب منك فيها شيئًا.',
    'docs_led_ideas' => 'ثلاث أفكار جديرة بالمعرفة',
    'docs_led_accrual' => 'الإيجار يُستحق أولاً ثم يُدفع',
    'docs_led_accrual_desc' => 'في كل دورة يُنشأ مستحق لكل عقد قائم. تلك هي اللحظة التي يصبح فيها الإيجار إيرادًا واللحظة التي يبدأ فيها المستأجر مدينًا — لا لحظة تسليمه المال. ثم تسدد الدفعة مستحقًا واحدًا أو أكثر، بدءًا من الأقدم. لهذا تكون المتأخرات دقيقة: الدفعة الجزئية تخفض المديونية بمقدار ما دُفع بالضبط، ولم يعد فائض شهر قادرًا على إخفاء عجز الشهر التالي.',
    'docs_led_float' => 'النقد الذي في يد شخص يُتابَع',
    'docs_led_float_desc' => 'حين يحصّل أحدهم نقدًا، فإنه لا يذهب إلى البنك مباشرة — بل يدخل صندوق نقد أو عهدته، وهي أموال محمولة نيابة عن الشركة. وحين يودعها يسجّل توريدًا. ولا ينخفض الرصيد إلا بعد أن يعتمد المعتمِد ذلك. وفي أي لحظة ترى بالضبط ما هو محتفَظ به وأين.',
    'docs_led_immutable' => 'القيود المرحَّلة لا تتغير أبدًا',
    'docs_led_immutable_desc' => 'بمجرد ترحيل القيد لا يمكن تعديله ولا حذفه. ويُصحَّح الخطأ بقيد عكسي يلغي الأصل، ويبقى الاثنان في السجل. وهذا ما يجعل كشفًا طبعته الشهر الماضي صحيحًا اليوم أيضًا.',
    'docs_led_setup' => 'التهيئة',
    'docs_led_setup_desc' => 'أربعة أمور، مرة واحدة، قبل أن يتمكن دفتر الأستاذ من ترحيل أي شيء:',
    'docs_led_s1' => '1. امنح شخصين صلاحية الاعتماد',
    'docs_led_s1_desc' => 'الإعدادات &rsaquo; المستخدمون، وعلّم على "يمكنه اعتماد الدفعات والتأمينات". شخصان إن أردت أن يحتاج خروج المال إلى عين ثانية؛ وواحد يكفي إن كنت تدير النظام وحدك وتركت الاعتماد الذاتي مفعّلًا.',
    'docs_led_s2' => '2. أنشئ حساباتك',
    'docs_led_s2_desc' => 'دفتر الأستاذ &rsaquo; دليل الحسابات &rsaquo; حساب جديد. أضف كل حساب بنكي (النوع: أصول، الصنف: حساب بنكي)، وأي صندوق نثرية، وحسابات المصروفات التي تريد التقرير عنها — كهرباء ورواتب وإصلاحات.',
    'docs_led_s3' => '3. اربط البنك الافتراضي',
    'docs_led_s3_desc' => 'دفتر الأستاذ &rsaquo; ربط الحسابات. يبقى سطر "الحساب البنكي الافتراضي" مميّزًا حتى تضبطه. ولا يمكن ترحيل التحويلات البنكية ودفعات البوابة قبل أن يشير إلى حساب حقيقي.',
    'docs_led_s4' => '4. جدوِل مولّد المستحقات',
    'docs_led_s4_desc' => 'مهمة يومية تنشئ مستحق الإيجار لكل عقد عند حلوله. ويجب أن تعمل قبل مهمتي رسوم التأخير والتذكيرات اللتين تقرآن تلك المستحقات. وبدونها تتجمد المتأخرات ولا يُطالَب أحد.',
    'docs_led_accounts' => 'دليل الحسابات',
    'docs_led_accounts_desc' => 'يمكنك إنشاء ما شئت من الحسابات. وبعضها يُنشأ لك ويُعلَّم بأنه من النظام — فالترحيلات التلقائية تعتمد عليه، ولذلك لا يمكن حذفه، وإن كان بإمكانك إعادة تسميته.',
    'docs_led_a_asset' => 'الأصول',
    'docs_led_a_asset_d' => 'الحسابات البنكية وصناديق النقد والعهد وما على المستأجرين لك',
    'docs_led_a_liab' => 'الالتزامات',
    'docs_led_a_liab_d' => 'التأمينات التي تحتفظ بها نيابة عن المستأجرين، وما عليك للموردين',
    'docs_led_a_eq' => 'حقوق الملكية',
    'docs_led_a_eq_d' => 'الأرصدة الافتتاحية والأرباح المتراكمة',
    'docs_led_a_inc' => 'الإيرادات',
    'docs_led_a_inc_d' => 'الإيجار ورسوم التأخير والخدمات المعاد تحصيلها والتأمينات المصادرة',
    'docs_led_a_exp' => 'المصروفات',
    'docs_led_a_exp_d' => 'كل ما تنفق فيه المال؛ أضف ما شئت مما تريد التقرير عنه',
    'docs_led_kind_note' => 'حقل "الصنف" ليس زينة — فهو يحدد أين يُعرض الحساب. فالحسابات المعلَّمة كحساب بنكي وحدها تظهر وجهةً عند إيداع النقد، والحسابات البنكية أو النقدية وحدها يمكن أن تكون مصدرًا عند دفع مصروف. أما الحساب المتروك كعام فيتاح للقيود اليدوية فقط.',
    'docs_led_currency_note' => 'كل حساب يحمل عملة واحدة. فحساب بنكي بالدولار حساب مستقل عن حساب بالشلن، ولا يمكن لقيد أن يخلط بين عملتين. ولهذا السبب نفسه تصدر الكشوف لكل عملة على حدة.',
    'docs_led_float_h' => 'العهد والتوريد',
    'docs_led_float_h_desc' => 'النقد يستقر في أحد موضعين. العهدة الشخصية تُنشأ تلقائيًا أول مرة يسجّل فيها أحدهم دفعة نقدية وتُسمّى باسمه. أما صندوق النقد المشترك فتنشئه أنت في دليل الحسابات — واضبط الصنف على نقد — ولا يخص أحدًا بعينه. وكلاهما يُودَع بالطريقة نفسها؛ والفرق أن العهدة تخبرك من كان يحمل المال، والصندوق المشترك لا يفعل.',
    'docs_led_f1' => 'يسجّل المحصِّل دفعة نقدية. فترتفع عهدته.',
    'docs_led_f2' => 'يودع المال في البنك، ثم يفتح دفتر الأستاذ &rsaquo; العهد وينقر "إيداع النقد"، مدخلاً المبلغ والحساب المستقبِل ورقم قسيمة الإيداع.',
    'docs_led_f3' => 'لا شيء يتحرك بعد. فالعهدة ما زالت تُظهر النقد.',
    'docs_led_f4' => 'يعتمدها شخص آخر. وعندئذ فقط تنخفض العهدة ويرتفع البنك.',
    'docs_led_f_note' => 'تُضبط الطرق التي تضع النقد في يد شخص من دفتر الأستاذ &rsaquo; ربط الحسابات. والنقد وحده افتراضيًا: فالشيك يُودَع في بنك لا يُحمَل، والتحويلات ودفعات البوابة لا تمر بيد أحد إطلاقًا.',
    'docs_led_approval' => 'ما الذي يحتاج اعتمادًا',
    'docs_led_approval_desc' => 'القاعدة بسيطة: تسجيل ما حدث لا يُمنع أبدًا، أما خروج المال فيحتاج دائمًا إلى شخص ثانٍ.',
    'docs_led_action' => 'الإجراء',
    'docs_led_needs' => 'الاعتماد',
    'docs_led_ap1' => 'تسجيل دفعة أو تأمين',
    'docs_led_no' => 'لا',
    'docs_led_ap2' => 'تسجيل مصروف لم يُدفع بعد',
    'docs_led_ap3' => 'إيداع النقد المحصَّل',
    'docs_led_yes' => 'نعم',
    'docs_led_ap4' => 'دفع مستحق لمورّد',
    'docs_led_ap5' => 'رد تأمين أو مصادرته',
    'docs_led_ap6' => 'قيد يدوي أو رصيد افتتاحي',
    'docs_led_self_note' => 'افتراضيًا يجوز للشخص اعتماد طلبه بنفسه، وهو ما يتيح لمالك يدير النظام وحده أن يعمل. أوقف "السماح باعتماد طلباتك بنفسك" من دفتر الأستاذ &rsaquo; ربط الحسابات، فيصير خروج المال محتاجًا دائمًا إلى شخص ثانٍ — وهو الضابط الوحيد هنا الذي لا يستطيع مستخدم واحد تجاوزه. ومع إيقافه ووجود معتمد واحد فقط، لن يُعتمد شيء أبدًا.',
    'docs_led_statements' => 'الكشوف',
    'docs_led_statements_desc' => 'يضم دفتر الأستاذ &rsaquo; الكشوف ثلاثة عروض، كلها لكل عملة:',
    'docs_led_st_pl' => 'الأرباح &amp; الخسائر',
    'docs_led_st_pl_d' => 'الإيرادات والمصروفات خلال مدة، مع إمكانية التصفية على عقار واحد. تُحتسب الإيرادات وقت استحقاقها والمصروفات وقت نشوئها، لا وقت حركة النقد.',
    'docs_led_st_bs' => 'الميزانية العمومية',
    'docs_led_st_bs_d' => 'ما تملكه وما عليك وما يتبقى، في أي تاريخ. وتُحسب الأرباح المحتجزة من كل الإيرادات والمصروفات حتى ذلك التاريخ.',
    'docs_led_st_ag' => 'أعمار الديون',
    'docs_led_st_ag_d' => 'من عليه ماذا، موزعًا بحسب مدة التأخر: جارٍ، و31–60، و61–90، وأكثر من 90 يومًا.',
    'docs_led_drill' => 'كل رقم رابط. انقر لتصل إلى دفتر ذلك الحساب فترى كل حركة برصيد متجدد، ومنه إلى القيد الذي وراءها. وإذا بدا رقم خاطئًا فهذا أسرع طريق لمعرفة السبب.',
    'docs_led_tb' => 'ميزان المراجعة هو فحص السلامة: يجب أن تساوي المدينة الدائنة. ويُتحقق من كل قيد عند حفظه، فإذا اختلّ يومًا فذلك يعني أن شيئًا غيّر قاعدة البيانات من خارج التطبيق.',
    'docs_led_closing' => 'إقفال فترة',
    'docs_led_closing_desc' => 'متى صدر التقرير عن شهر فأقفله: دفتر الأستاذ &rsaquo; ربط الحسابات &rsaquo; إقفال الدفاتر، واضبط التاريخ. عندها لا يمكن ترحيل شيء في ذلك التاريخ أو قبله — لا من شخص ولا من نداء API ولا من مهمة مجدولة. وامسح التاريخ لإعادة الفتح.',
    'docs_led_faq' => 'أسئلة شائعة',
    'docs_led_q1' => 'الجميع تظهر متأخراتهم صفرًا.',
    'docs_led_q1_a' => 'مولّد المستحقات لم يعمل. فالمتأخرات هي مجموع المستحقات غير المسددة، وما لم توجد مستحقات فلا شيء مستحق. شغّله يدويًا مرة، ثم جدوِله يوميًا.',
    'docs_led_q2' => 'دفعة لم تصل إلى دفتر الأستاذ.',
    'docs_led_q2_a' => 'في الغالب لم يُربط الحساب البنكي الافتراضي، أو لا يوجد حساب بعملة تلك الدفعة. والدفعة نفسها مسجَّلة بشكل صحيح — القيد وحده هو المفقود، ويمكن ترحيله بمجرد وجود الحساب.',
    'docs_led_q3' => 'عهدة ما زالت تُظهر نقدًا أُودع قبل أيام.',
    'docs_led_q3_a' => 'التوريد ينتظر الاعتماد. افتح كشف العهدة — يبيّن المبلغ المعلن الذي لم يُعتمد بعد، والرصيد الذي سيصير إليه بعد اعتماده.',
    'docs_led_q4' => 'هل أستطيع تعديل قيد رحّلته بالخطأ؟',
    'docs_led_q4_a' => 'لا، وهذا مقصود. افتح القيد وانقر عكس. فيُنشأ قيد مرآة يلغيه، وهو نفسه يحتاج اعتمادًا. ويبقى الاثنان في السجل.',
    'docs_led_q5' => 'تغيّرت المتأخرات عند تشغيل دفتر الأستاذ.',
    'docs_led_q5_a' => 'أمر متوقع. كانت المتأخرات تُقدَّر بعدد الأشهر المنقضية مضروبًا في الإيجار، ناقصًا كل ما دُفع. وصارت الآن المجموع الدقيق للمستحقات غير المسددة، فتظهر الدفعات الجزئية والتغييرات في منتصف المدة على وجهها الصحيح.',
