    'rep_up_margin' => 'الهامش',
    'rep_up_unallocated' => 'غير منسوبة إلى أي عقار',
    'rep_up_unallocated_help' => 'تُعرض هنا بدل تحميلها على الوحدات، ولهذا تكون الإجماليات أعلاه أقل من الأرباح والخسائر للفترة نفسها.',
    'rep_up_note' => 'التكاليف المسجلة على عقار دون وحدة — سقف أو حارس أو ماسورة المياه الرئيسية — تُوزَّع بنسبة إيجار كل وحدة. والوحدات الشاغرة مشمولة وتحمل حصتها، فخسارتها هي ما يكلفه الشغور. وتستخدم الحصة الإيجار الحالي لكل وحدة، فتغيير الإيجار يغيّر الفترات السابقة أيضًا.',
