    // Part 38 documentation
    'docs_led_receipt' => 'اختيار وجهة المبلغ المستلم',
    'docs_led_receipt_desc' => 'عند تسجيل دفعة أو تأمين يظهر حقل "استُلمت في". وما يعرضه يتبع طريقة الدفع: المبلغ النقدي لا يدخل إلا صندوق نقد أو عهدة، والتحويل أو الشيك لا يدخل إلا حسابًا بنكيًا. وليس هذا تشددًا — فإدخال مبلغ نقدي مباشرة إلى البنك يزعم أن المال وصل البنك ولم يأخذه أحد إلى هناك.',
    'docs_led_receipt_auto' => 'إن تُرك على "تحديد تلقائي" فسيعمل كما كان دائمًا: النقد إلى عهدة من سجّله، وكل ما عداه إلى الحساب المربوط كبنك افتراضي. اجعل لكل موضع يُحفَظ فيه المال صندوقًا — مكتب الاستقبال، مكتب الموقع — فتطابق الأرصدة ما في كل صندوق فعلًا.',

