    'lease_bill_from_edit_help' => 'لا تتم فوترة الإيجار قبل هذا التاريخ تلقائيًا. نقله إلى تاريخ أبكر يجعل النظام يفوتر الفترات السابقة في تشغيله التالي، فلا تفعل ذلك إلا إذا لم تتم فوترتها أو إدخالها كمتأخرات من قبل.',
